arguments.new_string:
    return VersionInfo(**version)

@staticmethod
def isvalid(version):
    """Return True if the given string is a valid semantic version.

    This method simply attempts to parse the version string using the
    :func:`parse` helper.  A :class:`ValueError` indicates the string does
    not conform to the semantic versioning specification.

    :param str version: Version string to validate.
    :return: ``True`` if valid, ``False`` otherwise.
    :rtype: bool
    """
    try:
        parse(version)
        return True
    except ValueError:
        return False
